import{_ as s,c as e,o as t,a0 as o}from"./chunks/framework.C1J0Vcxi.js";const b=JSON.parse('{"title":"K3 COM260 Kit 刷机流程：FIT 单文件烧录 + 可编辑设备树","description":"","frontmatter":{"title":"K3 COM260 Kit 刷机流程：FIT 单文件烧录 + 可编辑设备树","date":"2026-08-01T00:00:00.000Z","category":"技术报告"},"headers":[],"relativePath":"技术报告/2026-08-01-K3-COM260Kit-FIT烧录与可编辑设备树.md","filePath":"技术报告/2026-08-01-K3-COM260Kit-FIT烧录与可编辑设备树.md"}'),n={name:"技术报告/2026-08-01-K3-COM260Kit-FIT烧录与可编辑设备树.md"};function i(d,a,c,l,r,p){return t(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="k3-com260-kit-刷机流程-fit-单文件烧录-可编辑设备树" tabindex="-1">K3 COM260 Kit 刷机流程：FIT 单文件烧录 + 可编辑设备树 <a class="header-anchor" href="#k3-com260-kit-刷机流程-fit-单文件烧录-可编辑设备树" aria-label="Permalink to &quot;K3 COM260 Kit 刷机流程：FIT 单文件烧录 + 可编辑设备树&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>StarryOS 在 SpacemiT K3 COM260 Kit 真机上运行，之前的启动流程非常繁琐：</p><ol><li><strong>必须手动设置 bootargs</strong>。设备树里固化的是原厂 Linux 参数（<code>root=PARTUUID=...</code>），与 StarryOS 的 GPT 分区名（<code>rootfs</code>）不匹配，导致启动 panic：<code>configured root device was not found</code>。每次开机都要在 U-Boot 里 <code>setenv bootargs root=PARTLABEL=rootfs</code> 才能启动。</li><li><strong>内核与设备树分两次上传</strong>。fastboot 需要 U-Boot ↔ 宿主机来回配合两次（<code>fastboot stage</code> 内核 + <code>fastboot stage</code> 设备树），再 <code>booti</code> 指定两个加载地址。</li><li><strong>设备树不可编辑</strong>。<code>spacemit-k3-com260-ifx.dtb</code> 是编译后的二进制，想调整参数只能改回二进制或依赖反编译。</li></ol><p>本次改造一次性解决这三个问题：设备树改为<strong>可编辑的 dts 源码</strong>、bootargs <strong>固化进设备树</strong>、烧录流程合并为 <strong>FIT 单文件上传</strong>。</p><h2 id="相关文件" tabindex="-1">相关文件 <a class="header-anchor" href="#相关文件" aria-label="Permalink to &quot;相关文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>os/StarryOS/configs/board/spacemit-k3-com260-ifx.dts</code></td><td>设备树源码（可编辑）</td></tr><tr><td><code>os/StarryOS/configs/board/spacemit-k3-com260-ifx.dtb</code></td><td>由 dts 编译的设备树二进制</td></tr><tr><td><code>os/StarryOS/configs/board/spacemitk3-com260kit.its</code></td><td>FIT 镜像描述文件（内核 + 设备树打包）</td></tr><tr><td><code>os/StarryOS/configs/board/spacemitk3-com260kit.toml</code></td><td>K3 板级构建配置（触发 axbuild 自动打包）</td></tr></tbody></table><h2 id="刷机流程" tabindex="-1">刷机流程 <a class="header-anchor" href="#刷机流程" aria-label="Permalink to &quot;刷机流程&quot;">​</a></h2><h3 id="_1-构建内核-自动生成-fit-镜像" tabindex="-1">1. 构建内核（自动生成 FIT 镜像） <a class="header-anchor" href="#_1-构建内核-自动生成-fit-镜像" aria-label="Permalink to &quot;1. 构建内核（自动生成 FIT 镜像）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tgoskits</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> starry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> os/StarryOS/configs/board/spacemitk3-com260kit.toml</span></span></code></pre></div><p>由于 <code>spacemitk3-com260kit.toml</code> 同目录存在同名 <code>.its</code> 文件，axbuild 构建后会自动调用 <code>mkimage</code> 打包出 FIT 镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target/riscv64gc-unknown-none-elf/release/starryos.uimg</span></span></code></pre></div><p>镜像内含：</p><ul><li><strong>内核</strong>：加载地址 <code>0x140000000</code>（12.6 MiB）</li><li><strong>设备树</strong>：加载地址 <code>0x138000000</code>（139 KiB）</li><li>两者均带 sha256 校验</li></ul><h3 id="_2-上传并启动-u-boot-↔-宿主机各一次" tabindex="-1">2. 上传并启动（U-Boot ↔ 宿主机各一次） <a class="header-anchor" href="#_2-上传并启动-u-boot-↔-宿主机各一次" aria-label="Permalink to &quot;2. 上传并启动（U-Boot ↔ 宿主机各一次）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># U-Boot：一次会话，FIT 上传到 0x180000000（与内核/fdt 加载地址错开）</span></span>
<span class="line"><span>fastboot -l 0x180000000 -s 0x04000000 usb 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Host：一次上传</span></span>
<span class="line"><span>fastboot stage target/riscv64gc-unknown-none-elf/release/starryos.uimg</span></span>
<span class="line"><span></span></span>
<span class="line"><span># U-Boot：启动（FIT 自动解包，把内核搬到 0x140000000、fdt 搬到 0x138000000）</span></span>
<span class="line"><span>bootm 0x180000000</span></span></code></pre></div><p>bootargs 已固化在设备树里，<strong>无需手动 setenv</strong>。</p><h3 id="_3-验证" tabindex="-1">3. 验证 <a class="header-anchor" href="#_3-验证" aria-label="Permalink to &quot;3. 验证&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@starry:#</span></span>
<span class="line"><span>ls /dev/k3_airunner</span></span></code></pre></div><h2 id="设备树如何编辑" tabindex="-1">设备树如何编辑 <a class="header-anchor" href="#设备树如何编辑" aria-label="Permalink to &quot;设备树如何编辑&quot;">​</a></h2><p><code>spacemit-k3-com260-ifx.dts</code> 是 dts 源码，直接编辑后用 dtc 编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spacemit-k3-com260-ifx.dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spacemit-k3-com260-ifx.dtb</span></span></code></pre></div><p>当前 <code>chosen</code> 节点的 bootargs：</p><div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chosen {</span></span>
<span class="line"><span>    bootargs = &quot;console=ttyS0,115200 earlycon=sbi root=PARTLABEL=rootfs rw&quot;;</span></span>
<span class="line"><span>    boot-hartid = &lt;0x00&gt;;</span></span>
<span class="line"><span>    stdout-path = &quot;serial0:115200&quot;;</span></span>
<span class="line"><span>};</span></span></code></pre></div><ul><li><code>root=PARTLABEL=rootfs</code>：按 GPT 分区名定位根文件系统（K3 UFS 分区表的分区 3 名为 <code>rootfs</code>）</li><li>需要调整（如改串口、加调试参数）直接改这一行再编译即可</li></ul><blockquote><p><strong>注意</strong>：当前 dts 是反编译原厂 dtb 得到的，节点 phandle 是数字引用。日常维护只需编辑 <code>chosen</code> 等少量节点，改完编译回 dtb 时 phandle 保持一致，无需把整棵树重写为可读引用。</p></blockquote><h2 id="fit-打包机制说明" tabindex="-1">FIT 打包机制说明 <a class="header-anchor" href="#fit-打包机制说明" aria-label="Permalink to &quot;FIT 打包机制说明&quot;">​</a></h2><p>axbuild（<code>scripts/axbuild/src/starry/build.rs</code>）的 <code>uimage_generation_plan</code> 约定：</p><blockquote><p><strong>board 配置 <code>.toml</code> 同目录存在同名 <code>.its</code> 文件 → 构建后自动生成 <code>.uimg</code></strong></p></blockquote><p><code>spacemitk3-com260kit.its</code> 的要点：</p><div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>images {</span></span>
<span class="line"><span>    kernel {</span></span>
<span class="line"><span>        data = /incbin/(&quot;\${kernel_bin}&quot;);          // axbuild 渲染为绝对路径</span></span>
<span class="line"><span>        load = &lt;0x1 0x40000000&gt;;                   // 0x140000000</span></span>
<span class="line"><span>        entry = &lt;0x1 0x40000000&gt;;</span></span>
<span class="line"><span>        hash { algo = &quot;sha256&quot;; };</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>    fdt {</span></span>
<span class="line"><span>        data = /incbin/(&quot;../../../os/StarryOS/configs/board/spacemit-k3-com260-ifx.dtb&quot;);</span></span>
<span class="line"><span>        load = &lt;0x1 0x38000000&gt;;                   // 0x138000000</span></span>
<span class="line"><span>        hash { algo = &quot;sha256&quot;; };</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span></code></pre></div><ul><li><code>\${kernel_bin}</code> 由 axbuild 替换为内核 bin 的绝对路径</li><li>fdt 路径是<strong>相对渲染后 .its 所在目录</strong>（<code>target/riscv64gc-unknown-none-elf/release/</code>）的，<code>../../../</code> 上溯到 workspace 根目录</li><li>三个地址互不重叠：fdt <code>0x138000000</code> &lt; 内核 <code>0x140000000</code> &lt; FIT 上传点 <code>0x180000000</code></li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q1-error-new-format-image-overwritten-must-reset-the-board" tabindex="-1">Q1：<code>ERROR: new format image overwritten - must RESET the board</code> <a class="header-anchor" href="#q1-error-new-format-image-overwritten-must-reset-the-board" aria-label="Permalink to &quot;Q1：\`ERROR: new format image overwritten - must RESET the board\`&quot;">​</a></h3><p>FIT 镜像上传地址与内核/fdt 加载地址重叠。此前用 <code>fastboot -l 0x140000000</code> 上传 FIT，而内核 load 地址恰好也是 <code>0x140000000</code>，bootm 搬运内核时覆盖了 FIT 自身。</p><p><strong>解决</strong>：FIT 上传到与子镜像加载地址错开的地址，如 <code>0x180000000</code>。</p><h3 id="q2-configured-root-device-was-not-found-in-discovered-block-devices" tabindex="-1">Q2：<code>configured root device was not found in discovered block devices</code> <a class="header-anchor" href="#q2-configured-root-device-was-not-found-in-discovered-block-devices" aria-label="Permalink to &quot;Q2：\`configured root device was not found in discovered block devices\`&quot;">​</a></h3><p>bootargs 里的 <code>root=</code> 指定了不存在的分区。旧设备树固化的是原厂 <code>root=PARTUUID=9a52aa56-...</code>，与 StarryOS 的 GPT 分区名不匹配。当前 dts 已改为 <code>root=PARTLABEL=rootfs</code>，不再出现。</p><h3 id="q3-test-unit-ready-failed-retry-1" tabindex="-1">Q3：<code>TEST_UNIT_READY failed ... retry 1</code> <a class="header-anchor" href="#q3-test-unit-ready-failed-retry-1" aria-label="Permalink to &quot;Q3：\`TEST_UNIT_READY failed ... retry 1\`&quot;">​</a></h3><p>UFS 设备上电后返回 <code>UNIT_ATTENTION</code>（sense key 0x06/asc 0x29 = power-on reset），驱动重试后成功，是正常行为。</p><h2 id="待改进项" tabindex="-1">待改进项 <a class="header-anchor" href="#待改进项" aria-label="Permalink to &quot;待改进项&quot;">​</a></h2><ul><li><strong><code>\${dtb_bin}</code> 占位符</strong>：当前 fdt 路径是手写的相对路径，与 <code>mkimage</code> 的解析基准（.its 所在目录）耦合。后续可在 axbuild 的 <code>render_uimage_its_template</code> 增加 <code>\${dtb_bin}</code> 占位符，像 <code>\${kernel_bin}</code> 一样由 axbuild 替换为绝对路径，消除路径魔法。</li><li><strong><code>starry-mininal-k32-.its</code> 孤儿文件</strong>：K32 设备的遗留文件（K3 ≠ K32），无匹配的 board 配置，永远不会被构建触发，可择机清理。</li></ul>`,42)])])}const g=s(n,[["render",i]]);export{b as __pageData,g as default};
